python3 -c "
import json, sys
data = json.load(open('/tmp/deployed_asset.json'))
# Print top-level keys and a snippet
if isinstance(data, dict):
    print('keys:', list(data.keys()))
    # Look for BPMN content
    for k,v in data.items():
        if isinstance(v, str) and '<bpmn' in v:
            print(f'key {k!r} contains BPMN XML, length={len(v)}')
            print(v[:2000])
        elif isinstance(v, str):
            print(f'key {k!r}: {v[:200]}')
        else:
            print(f'key {k!r}: {type(v).__name__}')
"

